describe('Clear All Filters Button', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should clear all applied filters when clear all button is clicked', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category-electronics"]').click();
    cy.get('[data-testid="filter-price-range-0-100"]').click();
    cy.get('[data-testid="filter-brand-samsung"]').click();

    // Verify filters are applied
    cy.get('[data-testid="filter-category-electronics"]').should('have.class', 'active');
    cy.get('[data-testid="filter-price-range-0-100"]').should('have.class', 'active');
    cy.get('[data-testid="filter-brand-samsung"]').should('have.class', 'active');

    // Verify search results are displayed with filters
    cy.get('[data-testid="search-results-count"]').should('contain', 'results');

    // Click clear all filters button
    cy.get('[data-testid="clear-all-filters-button"]').click();

    // Verify all filters are cleared
    cy.get('[data-testid="filter-category-electronics"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-price-range-0-100"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-brand-samsung"]').should('not.have.class', 'active');

    // Verify search results are reset
    cy.get('[data-testid="search-results-count"]').should('contain', 'all results');
    cy.get('[data-testid="search-results-list"]').should('be.visible');
  });

  it('should handle clicking clear all filters when no filters are applied', () => {
    // Verify no filters are applied initially
    cy.get('[data-testid="filter-category-electronics"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-price-range-0-100"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-brand-samsung"]').should('not.have.class', 'active');

    // Verify clear all button is disabled or hidden when no filters are applied
    cy.get('[data-testid="clear-all-filters-button"]').should('be.disabled');

    // Attempt to click the disabled button
    cy.get('[data-testid="clear-all-filters-button"]').click({ force: true });

    // Verify no state change occurs
    cy.get('[data-testid="filter-category-electronics"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-price-range-0-100"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-brand-samsung"]').should('not.have.class', 'active');

    // Verify search results remain unchanged
    cy.get('[data-testid="search-results-count"]').should('contain', 'all results');
  });
});
